-- АВТОМАТААР ҮҮСГЭСЭН: data/questions.json-оос (npm run seed:build)
-- Supabase → SQL Editor дээр schema.sql-ийн дараа ажиллуулна. Дахин ажиллуулахад аюулгүй.
insert into public.questions (slug, domain, skill, difficulty, type, prompt, choices, answer, explanation)
values
  ('alg-01', 'algebra', 'Нэг хувьсагчтай шугаман тэгшитгэл', 'easy', 'mcq', 'Хэрэв $3x + 7 = 22$ бол $x$-ийн утга хэд вэ?', '["$3$","$5$","$7$","$15$"]'::jsonb, 'B', 'Хоёр талаас 7-г хасна: $3x = 15$. Хоёр талыг 3-т хуваавал $x = 5$.'),
  ('alg-02', 'algebra', 'Шугаман функц', 'easy', 'mcq', '$f(x) = 4x - 9$ функцийн хувьд $f(5)$-ийн утга хэд вэ?', '["$11$","$20$","$29$","$-1$"]'::jsonb, 'A', '$x$-ийн оронд 5-ыг орлуулна: $f(5) = 4 \cdot 5 - 9 = 20 - 9 = 11$.'),
  ('alg-03', 'algebra', 'Шугаман тэгшитгэлийн систем', 'medium', 'mcq', 'Дараах системийн шийдийн хувьд $x$-ийн утга хэд вэ?

$$x + y = 10$$
$$x - y = 4$$', '["$3$","$6$","$7$","$14$"]'::jsonb, 'C', 'Хоёр тэгшитгэлийг нэмбэл $y$ устана: $2x = 14$, иймд $x = 7$. (Шалгалт: $y = 3$, $7 + 3 = 10$, $7 - 3 = 4$.)'),
  ('alg-04', 'algebra', 'Хоёр хувьсагчтай шугаман тэгшитгэл', 'medium', 'spr', '$xy$ хавтгай дээрх шулуун $(2,\ 5)$ ба $(6,\ 17)$ цэгүүдийг дайрдаг. Энэ шулууны налалт хэд вэ?', null, '3', 'Налалт $= \dfrac{y_2 - y_1}{x_2 - x_1} = \dfrac{17 - 5}{6 - 2} = \dfrac{12}{4} = 3$.'),
  ('alg-05', 'algebra', 'Шугаман тэнцэтгэл биш', 'medium', 'mcq', 'Таксины үнэ суултын 2 000₮ дээр километр тутамд 1 500₮ нэмэгддэг. Батад 20 000₮ байгаа бол тэр хамгийн ихдээ хэдэн бүтэн километр явж чадах вэ?', '["$10$","$12$","$13$","$14$"]'::jsonb, 'B', '$k$ км явахад үнэ $2000 + 1500k$ болно. $2000 + 1500k \le 20000$ $\Rightarrow$ $1500k \le 18000$ $\Rightarrow$ $k \le 12$. Иймд хамгийн ихдээ 12 км.'),
  ('alg-06', 'algebra', 'Шугаман тэгшитгэлийн систем', 'hard', 'spr', 'Дараах систем шийдгүй байх $k$-ийн утга хэд вэ?

$$2x + 3y = 12$$
$$4x + ky = 20$$', null, '6', 'Систем шийдгүй байхын тулд хоёр шулуун параллель (налалт ижил), гэхдээ давхцахгүй байх ёстой. Эхний тэгшитгэлийг 2-оор үржүүлбэл $4x + 6y = 24$. Иймд $k = 6$ үед $4x + 6y = 20$ ба $4x + 6y = 24$ болж, зүүн тал ижил, баруун тал өөр тул шийдгүй.'),
  ('alg-07', 'algebra', 'Шугаман функц', 'medium', 'mcq', 'Саванд 1 200 литр ус байна. Минут тутамд 15 литр ус гоожиж байгаа бол $t$ минутын дараах усны хэмжээг $V(t)$ литрээр илэрхийлсэн функц аль нь вэ?', '["$V(t) = 1200 + 15t$","$V(t) = 1200 - 15t$","$V(t) = 15 - 1200t$","$V(t) = 1200t - 15$"]'::jsonb, 'B', 'Эхний хэмжээ 1 200 л, минут тутам 15 л-ээр буурна. Иймд $V(t) = 1200 - 15t$.'),
  ('alg-08', 'algebra', 'Нэг хувьсагчтай шугаман тэгшитгэл', 'hard', 'spr', 'Хэрэв $\dfrac{2x - 1}{3} = \dfrac{x + 4}{2}$ бол $x$-ийн утга хэд вэ?', null, '14', 'Хоёр талыг 6-аар үржүүлнэ: $2(2x - 1) = 3(x + 4)$ $\Rightarrow$ $4x - 2 = 3x + 12$ $\Rightarrow$ $x = 14$.'),
  ('adv-01', 'advanced_math', 'Тэнцүү илэрхийлэл', 'easy', 'mcq', '$(x + 3)^2$ илэрхийлэлтэй тэнцүү илэрхийлэл аль нь вэ?', '["$x^2 + 9$","$x^2 + 3x + 9$","$x^2 + 6x + 9$","$x^2 + 6x + 3$"]'::jsonb, 'C', '$(a + b)^2 = a^2 + 2ab + b^2$ томьёогоор: $(x + 3)^2 = x^2 + 2 \cdot 3 \cdot x + 9 = x^2 + 6x + 9$.'),
  ('adv-02', 'advanced_math', 'Шугаман бус тэгшитгэл', 'medium', 'mcq', '$x^2 - 5x + 6 = 0$ тэгшитгэлийн шийдүүдийн нийлбэр хэд вэ?', '["$-5$","$1$","$5$","$6$"]'::jsonb, 'C', 'Үржигдэхүүнд задлавал $(x - 2)(x - 3) = 0$, шийдүүд нь $2$ ба $3$. Нийлбэр $= 5$. (Виетийн теоремоор нийлбэр $= -\frac{b}{a} = 5$.)'),
  ('adv-03', 'advanced_math', 'Шугаман бус функц', 'medium', 'spr', '$g(x) = 2x^2 - 3x + 1$ бол $g(-2)$-ийн утга хэд вэ?', null, '15', '$g(-2) = 2(-2)^2 - 3(-2) + 1 = 2 \cdot 4 + 6 + 1 = 15$.'),
  ('adv-04', 'advanced_math', 'Шугаман бус функц', 'medium', 'mcq', 'Нэгэн бактерийн тоо цаг тутамд 2 дахин өсдөг. Эхэндээ 300 бактери байсан бол 4 цагийн дараа хэд болох вэ?', '["$1\\,200$","$2\\,400$","$4\\,800$","$9\\,600$"]'::jsonb, 'C', 'Энэ нь илтгэгч функц: $N(t) = 300 \cdot 2^t$. $N(4) = 300 \cdot 2^4 = 300 \cdot 16 = 4800$.'),
  ('adv-05', 'advanced_math', 'Тэнцүү илэрхийлэл', 'medium', 'mcq', '$x \ne 3$ үед $\dfrac{x^2 - 9}{x - 3}$ илэрхийлэлтэй тэнцүү илэрхийлэл аль нь вэ?', '["$x - 3$","$x + 3$","$x^2 - 3$","$3$"]'::jsonb, 'B', 'Квадратуудын ялгаврын томьёо: $x^2 - 9 = (x - 3)(x + 3)$. Иймд $\dfrac{(x - 3)(x + 3)}{x - 3} = x + 3$.'),
  ('adv-06', 'advanced_math', 'Шугаман бус тэгшитгэлийн систем', 'hard', 'spr', '$xy$ хавтгайд $y = x^2 - 4x + 7$ парабол ба $y = k$ шулуун яг нэг цэгт огтлолцдог. $k$-ийн утга хэд вэ?', null, '3', '$y = k$ хэвтээ шулуун параболтой яг нэг цэгт огтлолцох нь параболын оройгоор дайрах үед. Бүтэн квадрат болговол $y = (x - 2)^2 + 3$, орой нь $(2,\ 3)$. Иймд $k = 3$.'),
  ('adv-07', 'advanced_math', 'Шугаман бус тэгшитгэл', 'hard', 'mcq', '$x^2 + bx + 16 = 0$ тэгшитгэл яг нэг бодит шийдтэй ба $b > 0$ бол $b$-ийн утга хэд вэ?', '["$4$","$8$","$16$","$32$"]'::jsonb, 'B', 'Яг нэг бодит шийдтэй байхын тулд дискриминант 0 байна: $b^2 - 4 \cdot 1 \cdot 16 = 0$ $\Rightarrow$ $b^2 = 64$ $\Rightarrow$ $b = 8$ ($b > 0$).'),
  ('adv-08', 'advanced_math', 'Тэнцүү илэрхийлэл', 'hard', 'spr', '$(2x + 5)(x - 3) = 2x^2 + ax - 15$ нь бүх $x$-ийн хувьд үнэн бол $a$-ийн утга хэд вэ?', null, '-1', 'Зүүн талыг задлавал $2x^2 - 6x + 5x - 15 = 2x^2 - x - 15$. Иймд $a = -1$.'),
  ('psd-01', 'problem_solving', 'Хувь', 'easy', 'mcq', '80 000₮-ийн үнэтэй цүнх 25%-ийн хямдралтай болжээ. Хямдарсан үнэ хэд вэ?', '["20 000₮","55 000₮","60 000₮","64 000₮"]'::jsonb, 'C', '25% хямдрал гэдэг нь үнийн $75\%$-ийг төлнө гэсэн үг: $80\,000 \cdot 0.75 = 60\,000$₮.'),
  ('psd-02', 'problem_solving', 'Харьцаа, хурд, пропорц', 'easy', 'spr', 'Нэгэн жоронд 3 аяга гурил тутамд 2 аяга сүү хэрэглэдэг. 12 аяга гурил хэрэглэвэл хэдэн аяга сүү хэрэгтэй вэ?', null, '8', 'Пропорц: $\dfrac{3}{2} = \dfrac{12}{s}$ $\Rightarrow$ $3s = 24$ $\Rightarrow$ $s = 8$ аяга.'),
  ('psd-03', 'problem_solving', 'Нэг хувьсагчтай өгөгдөл', 'medium', 'mcq', '5 сурагчийн шалгалтын оноо: 70, 85, 90, 75, 80. Эдгээр онооны арифметик дундаж хэд вэ?', '["$75$","$80$","$82$","$85$"]'::jsonb, 'B', 'Нийлбэр $= 70 + 85 + 90 + 75 + 80 = 400$. Дундаж $= \dfrac{400}{5} = 80$.'),
  ('psd-04', 'problem_solving', 'Нэг хувьсагчтай өгөгдөл', 'medium', 'mcq', 'Өгөгдлийн олонлог: 4, 7, 7, 9, 12, 15. Медиан нь хэд вэ?', '["$7$","$8$","$9$","$9.5$"]'::jsonb, 'B', 'Өгөгдөл эрэмбэлэгдсэн, 6 утгатай (тэгш тоо). Медиан нь дунд орших хоёр утгын дундаж: $\dfrac{7 + 9}{2} = 8$.'),
  ('psd-05', 'problem_solving', 'Магадлал', 'medium', 'mcq', 'Уутанд 4 улаан, 6 цэнхэр, 5 ногоон бөмбөг байна. Санамсаргүйгээр нэг бөмбөг авахад ногоон байх магадлал хэд вэ?', '["$\\frac{1}{5}$","$\\frac{1}{4}$","$\\frac{1}{3}$","$\\frac{2}{5}$"]'::jsonb, 'C', 'Нийт бөмбөг $= 4 + 6 + 5 = 15$. Ногоон $= 5$. Магадлал $= \dfrac{5}{15} = \dfrac{1}{3}$.'),
  ('psd-06', 'problem_solving', 'Хувь', 'hard', 'spr', 'Нэгэн барааны үнийг эхлээд 20%-иар нэмээд, дараа нь шинэ үнийг 20%-иар бууруулсан. Эцсийн үнэ анхны үнээсээ хэдэн хувиар бага вэ?', null, '4', 'Анхны үнийг $P$ гэе. $P \cdot 1.2 \cdot 0.8 = 0.96P$. Иймд эцсийн үнэ анхныхаас $4\%$-иар бага. (Анхаар: 0% биш!)'),
  ('psd-07', 'problem_solving', 'Харьцаа, хурд, пропорц', 'hard', 'mcq', 'Машин цагт 90 км хурдтай тогтмол явж байна. 25 минутад хэдэн километр явах вэ?', '["$22.5$","$36$","$37.5$","$40$"]'::jsonb, 'C', '25 минут $= \dfrac{25}{60}$ цаг. Зам $= 90 \cdot \dfrac{25}{60} = 37.5$ км.'),
  ('psd-08', 'problem_solving', 'Статистик дүгнэлт', 'medium', 'mcq', 'Нэгэн сургуулийн 1 500 сурагчаас санамсаргүйгээр сонгосон 200 сурагчийн 120 нь өглөөний цай уудаг гэж хариулжээ. Энэ сургуулийн нийт сурагчдаас ойролцоогоор хэд нь өглөөний цай уудаг гэж үнэлэх вэ?', '["$600$","$750$","$900$","$1\\,200$"]'::jsonb, 'C', 'Түүврийн эзлэх хувь $= \dfrac{120}{200} = 0.6$. Нийт сурагчдад хэрэглэвэл $0.6 \cdot 1500 = 900$.'),
  ('geo-01', 'geometry_trig', 'Талбай ба эзлэхүүн', 'easy', 'mcq', 'Тэгш өнцөгтийн урт нь 12, өргөн нь 5 бол талбай нь хэд вэ?', '["$17$","$34$","$60$","$120$"]'::jsonb, 'C', 'Тэгш өнцөгтийн талбай $=$ урт $\times$ өргөн $= 12 \cdot 5 = 60$.'),
  ('geo-02', 'geometry_trig', 'Шулуун, өнцөг, гурвалжин', 'easy', 'spr', 'Гурвалжны хоёр өнцөг нь $50^\circ$ ба $65^\circ$ бол гурав дахь өнцөг хэдэн градус вэ?', null, '65', 'Гурвалжны өнцгүүдийн нийлбэр $180^\circ$. $180 - 50 - 65 = 65^\circ$.'),
  ('geo-03', 'geometry_trig', 'Тэгш өнцөгт гурвалжин ба тригонометр', 'medium', 'mcq', 'Тэгш өнцөгт гурвалжны катетууд 6 ба 8 урттай. Гипотенузын урт хэд вэ?', '["$10$","$12$","$14$","$48$"]'::jsonb, 'A', 'Пифагорын теорем: $c^2 = 6^2 + 8^2 = 36 + 64 = 100$, $c = 10$.'),
  ('geo-04', 'geometry_trig', 'Тэгш өнцөгт гурвалжин ба тригонометр', 'medium', 'mcq', '$C$ өнцөг нь тэгш өнцөг байх $ABC$ гурвалжинд $\sin A = \dfrac{3}{5}$ бол $\cos A$-ийн утга хэд вэ?', '["$\\frac{3}{4}$","$\\frac{4}{5}$","$\\frac{5}{3}$","$\\frac{5}{4}$"]'::jsonb, 'B', '$\sin A = \dfrac{\text{эсрэг катет}}{\text{гипотенуз}} = \dfrac{3}{5}$. Пифагороор хүрэлцэх катет $= \sqrt{5^2 - 3^2} = 4$. Иймд $\cos A = \dfrac{4}{5}$.'),
  ('geo-05', 'geometry_trig', 'Тойрог', 'medium', 'spr', 'Тойргийн радиус 7 бол талбай нь $k\pi$ байна. $k$-ийн утга хэд вэ?', null, '49', 'Тойргийн талбай $= \pi r^2 = \pi \cdot 7^2 = 49\pi$. Иймд $k = 49$.'),
  ('geo-06', 'geometry_trig', 'Тойрог', 'hard', 'mcq', '$xy$ хавтгайд $x^2 + y^2 - 6x + 4y - 12 = 0$ тэгшитгэлээр өгөгдсөн тойргийн радиус хэд вэ?', '["$5$","$12$","$25$","$\\sqrt{12}$"]'::jsonb, 'A', 'Бүтэн квадрат болгоно: $(x^2 - 6x + 9) + (y^2 + 4y + 4) = 12 + 9 + 4$ $\Rightarrow$ $(x - 3)^2 + (y + 2)^2 = 25$. Радиус $= \sqrt{25} = 5$.'),
  ('geo-07', 'geometry_trig', 'Талбай ба эзлэхүүн', 'hard', 'spr', 'Цилиндрийн суурийн радиус 3, өндөр нь 10. Эзлэхүүн нь $k\pi$ бол $k$-ийн утга хэд вэ?', null, '90', 'Цилиндрийн эзлэхүүн $= \pi r^2 h = \pi \cdot 9 \cdot 10 = 90\pi$. Иймд $k = 90$.'),
  ('geo-08', 'geometry_trig', 'Шулуун, өнцөг, гурвалжин', 'hard', 'mcq', 'Хоёр төстэй гурвалжны харгалзах талуудын харьцаа $2 : 3$. Бага гурвалжны талбай 20 бол их гурвалжны талбай хэд вэ?', '["$30$","$40$","$45$","$60$"]'::jsonb, 'C', 'Төстэй дүрсийн талбайн харьцаа нь талуудын харьцааны квадрат: $\left(\dfrac{3}{2}\right)^2 = \dfrac{9}{4}$. Их гурвалжны талбай $= 20 \cdot \dfrac{9}{4} = 45$.')
on conflict (slug) do update set
  domain = excluded.domain,
  skill = excluded.skill,
  difficulty = excluded.difficulty,
  type = excluded.type,
  prompt = excluded.prompt,
  choices = excluded.choices,
  answer = excluded.answer,
  explanation = excluded.explanation;
